import pandas as pd

def clean(df):
    df = df.copy()
    # fix species label variants (extra spaces, case)
    if 'species' in df.columns:
        df['species'] = df['species'].astype('string').str.strip()
        allowed_species = ['Adelie', 'Chinstrap', 'Gentoo']
        lower_map = {a.lower(): a for a in allowed_species}
        df['species'] = df['species'].apply(lambda x: lower_map.get(x.lower(), x) if isinstance(x, str) else x)
    # fix island label variants (case variant biscoe)
    if 'island' in df.columns:
        df['island'] = df['island'].astype('string').str.strip()
        allowed_island = ['Biscoe', 'Dream', 'Torgersen']
        lower_map_i = {a.lower(): a for a in allowed_island}
        df['island'] = df['island'].apply(lambda x: lower_map_i.get(x.lower(), x) if isinstance(x, str) else x)
    # fix body_mass_g text_number with commas
    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = df['body_mass_g'].astype(str).str.replace(',', '', regex=False).str.strip()
        df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
        # enforce valid range 2500-6500 per rules
        df.loc[(df['body_mass_g'] < 2500) | (df['body_mass_g'] > 6500), 'body_mass_g'] = pd.NA
    # ensure flipper_length_mm numeric (if stored as text)
    if 'flipper_length_mm' in df.columns:
        df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'].astype(str).str.replace(',', '', regex=False), errors='coerce')
    return df

def answer(df):
    # average body_mass_g for each species
    if 'species' not in df.columns or 'body_mass_g' not in df.columns:
        return {}
    # drop missing group keys
    d = df.dropna(subset=['species'])
    # ensure body_mass_g is numeric
    d['body_mass_g'] = pd.to_numeric(d['body_mass_g'], errors='coerce')
    grouped = d.groupby('species', dropna=True)['body_mass_g'].mean()
    return {str(k): float(v) for k, v in grouped.items() if pd.notna(k) and pd.notna(v)}
